v(lgt_atom_chars_2_20, true(v(A,B,C) == v('A','B','C')), (atom_chars('ABC', [A,B,C]))).
v(lgt_atom_chars_2_21, true, (atom_chars('ABC', ['A','B','C']))).
v(lgt_atom_chars_2_22, false, (atom_chars('ABC', ['B'| _]))).
v(lgt_atom_chars_2_23, error(type_error(list,['B'| 'C'])), (atom_chars('ABC', ['B'| 'C']))).
